import type { Offer } from '@/types';
import raw from './catalogue.json';

/**
 * The 1 offer catalogue, generated by scripts/build-catalogue.mjs from the
 * supplied DY product feed plus generated demo offers.
 */
export const catalogue: Offer[] = raw as Offer[];

const byId = new Map(catalogue.map((o) => [o.id, o]));

/** Look up an offer by SKU. Throws in dev if a scripted SKU is missing. */
export function offer(id: string): Offer {
  const o = byId.get(id);
  if (!o) throw new Error(`Unknown offer SKU ${id}`);
  return o;
}

export const offers = (ids: string[]): Offer[] => ids.map(offer);

export const offersByBrand = (brandId: string): Offer[] => catalogue.filter((o) => o.brandId === brandId);

/** Brands that share the Tops hub (Tops, Tops Online, Tops daily…). */
export const topsHubOffers = (): Offer[] => catalogue.filter((o) => o.topsFamily);

