/** Expand a query into the keyword set used for semantic matching. */
export function expandQuery(q: string): string[] {
  const words = q.toLowerCase().trim().split(/\s+/).filter(Boolean);
  const out = new Set<string>(words);
  for (const w of words) (synonyms[w] ?? []).forEach((s) => out.add(s));
  if (synonyms[q.toLowerCase().trim()]) synonyms[q.toLowerCase().trim()].forEach((s) => out.add(s));
  return [...out];
}

/** Semantic-ish search: name/brand match first, then tag matches via synonyms. */
export function searchOffers(q: string): { exact: Offer[]; semantic: Offer[] } {
  const raw = q.toLowerCase().trim();
  if (!raw) return { exact: [], semantic: [] };
  const terms = expandQuery(raw);
  const exact = catalogue.filter((o) => `${o.name} ${o.brand} ${o.title}`.toLowerCase().includes(raw));
  const seen = new Set(exact.map((o) => o.id));
  const semantic = catalogue.filter((o) => !seen.has(o.id) && o.tags.some((t) => terms.includes(t)));
  return { exact, semantic };
}

/** User-margin: how many points buy ฿1 of value. Lower is better; 8 is the universal benchmark. */
export function pointsPerBaht(o: Offer): number | null {
  if (o.pointsCost <= 0) return null;
  const value = o.valueThb ?? o.discountThb;
  if (!value) return null;
  return Math.round((o.pointsCost / value) * 10) / 10;
}

/** Headline value in THB for a coupon or perk. */
export function offerValueThb(o: Offer): number | undefined {
  return o.valueThb ?? o.discountThb;
}
